let wxTab='chat';
function isChatView(){return tab==='wechat'&&wxTab==='chat'}
function isMomentsView(){return tab==='wechat'&&wxTab==='moments'}
function configureDock(){const d=$('.dock');d.classList.toggle('wx-dock',tab==='wechat');d.setAttribute('aria-label',tab==='wechat'?'微信导航':'手机导航');d.innerHTML=tab==='wechat'?[['chat','♡','聊天'],['contacts','♧','联系人'],['moments','❀','朋友圈'],['wxme','♙','我']].map(([t,i,n])=>`<button data-wx="${t}" class="${wxTab===t?'active':''}"><span>${i}</span>${n}</button>`).join(''):[['home','⌂','桌面'],['calendar','▦','日历'],['api','⚙','API'],['me','♙','我的']].map(([t,i,n])=>`<button data-tab="${t}" class="${tab===t?'active':''}"><span>${i}</span>${n}</button>`).join('');d.querySelectorAll('[data-wx]').forEach(b=>b.onclick=()=>{current=null;go(b.dataset.wx)});d.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{current=null;go(b.dataset.tab)});notificationDots();}
function renderWechat(){if(wxTab==='contacts')renderContacts();else if(wxTab==='moments')renderMoments();else if(wxTab==='wxme')renderWxMe();else if(current)renderConversation();else renderChatList();}
function wxHeading(name,en,extra=''){return title(name,en,`<div class="wx-head-actions"><button class="text-button" id="wxHome" aria-label="退出微信回到手机桌面">⌂</button>${extra}</div>`)}
function bindWxHome(){if($('#wxHome'))$('#wxHome').onclick=()=>go('home')}
function renderContacts(){screen.innerHTML=`<section class="view">${wxHeading('联系人','WECHAT · CONTACTS','<button class="round" id="newContact" aria-label="添加联系人">+</button>')}<label class="contact-search">搜索联系人<input id="searchContact" placeholder="输入名字查找角色"></label><div class="contact-tools"><button class="menu-button" id="contactGroups">群聊 <span>${groups.length} 个 ›</span></button></div><div class="contact-caption">我的角色 · ${roles.length} 位</div><div id="contactsList"></div></section>`;bindWxHome();$('#newContact').onclick=()=>editRole();$('#contactGroups').onclick=()=>{current=null;go('chat')};const list=$('#contactsList'),show=()=>{const value=$('#searchContact').value.trim().toLowerCase();list.innerHTML='';roles.filter(r=>r.name.toLowerCase().includes(value)).sort((a,b)=>a.name.localeCompare(b.name,'zh-CN')).forEach(r=>{const b=document.createElement('button');b.className='role contact-row';b.innerHTML=avatarHTML('role:'+r.id,r.emoji)+`<strong>${escapeHtml(r.name)}</strong><span>›</span>`;b.onclick=()=>contactDetails(r);list.append(b)});if(!list.children.length)list.innerHTML='<div class="soft-empty">没有找到联系人</div>'};$('#searchContact').oninput=show;show()}
function contactDetails(r){const d=panel(`<div class="wx-contact-profile">${avatarHTML('role:'+r.id,r.emoji)}<h2>${escapeHtml(r.name)}</h2><p>你的私人角色联系人</p></div><button class="primary full" id="contactChat">发消息</button><button class="menu-button" id="contactEdit">编辑角色与头像 <span>›</span></button><button class="secondary full" id="closeContact">关闭</button>`);$('#contactChat').onclick=()=>{d.close();current=r.id;go('chat')};$('#contactEdit').onclick=()=>{d.close();editRole(r.id)};$('#closeContact').onclick=()=>d.close()}
function renderWxMe(){screen.innerHTML=`<section class="view">${wxHeading('我','WECHAT · MY SPACE')}<button class="wx-profile" id="wxProfile">${avatarHTML('profile','🎀')}<div><strong>${escapeHtml(profile.name)}</strong><small>拍一拍：${escapeHtml(profile.pat||'的肩膀')}</small></div><span>›</span></button><button class="wx-wallet-card" id="wxWallet"><span>零钱 · 虚拟余额</span><strong>¥ ${PalaisWallet.money(wallet.balance)}</strong><small>查看收支明细 ›</small></button><div class="wx-settings-title">微信设置</div><button class="menu-button" id="wxAvatar">头像与昵称 <span>›</span></button><button class="menu-button" id="wxPat">拍一拍 <span>${escapeHtml(profile.pat||'的肩膀')} ›</span></button><button class="menu-button" id="wxBackground">通用聊天背景 <span>›</span></button><button class="menu-button" id="wxTheme">主题配色 <span>${escapeHtml(themeName())} ›</span></button><button class="menu-button" id="wxAPI">聊天 API / 语音 API <span>›</span></button><button class="menu-button" id="wxRelations">角色认识关系 <span>›</span></button><button class="menu-button" id="wxProactive">主动来找你 <span>›</span></button><button class="menu-button" id="wxMemory">长期记忆 <span>›</span></button><p class="section-note">零钱仅用于小手机里的虚拟红包和转账。<br>新浏览器初始 ¥10,000.00，不涉及真实资金。</p></section>`;bindWxHome();$('#wxProfile').onclick=renderProfile;$('#wxAvatar').onclick=renderProfile;$('#wxPat').onclick=editPat;$('#wxBackground').onclick=editDefaultBackground;$('#wxTheme').onclick=()=>openThemePicker(renderWxMe);$('#wxWallet').onclick=renderWallet;$('#wxAPI').onclick=()=>go('api');$('#wxMemory').onclick=()=>go('memory');$('#wxRelations').onclick=openRelationships;$('#wxProactive').onclick=()=>go('proactive')}
function renderProfileHome(){tab==='wechat'?renderWxMe():renderMe()}
function editPat(){const d=panel(`<form id="patForm"><h2>设置拍一拍</h2><label>拍一拍后缀<input name="suffix" maxlength="30" value="${escapeHtml(profile.pat||'的肩膀')}" placeholder="例如：的肩膀，说今天也要开心"></label><div class="notice" id="patPreview"></div><p class="api-note">在聊天中双击头像即可拍一拍。</p><div class="actions"><button class="secondary" type="button" id="cancelPat">取消</button><button class="primary">保存</button></div></form>`);const f=$('#patForm'),preview=()=>{$('#patPreview').textContent='对方拍了拍「'+profile.name+'」'+f.suffix.value};f.suffix.oninput=preview;preview();$('#cancelPat').onclick=()=>d.close();f.onsubmit=e=>{e.preventDefault();const next={...profile,pat:f.suffix.value.trim()||'的肩膀'};try{localSave('profile',next);profile=next;d.close();renderWxMe();toast('拍一拍已保存')}catch{toast('保存失败，请检查存储空间')}}}
function editDefaultBackground(){const d=panel(`<h2>通用聊天背景</h2><p class="api-note">用于没有单独设置背景的聊天。单独背景会优先显示。</p><div class="background-preview" id="defaultBgPreview">${mediaCache.has('background:default')?'':'浅粉默认背景'}</div>${fileInput('defaultBgFile')}<div class="actions"><button class="secondary" id="resetDefaultBg">恢复默认</button><button class="primary" id="chooseDefaultBg">上传背景</button></div><button class="secondary full" id="doneDefaultBg">完成</button>`);const show=()=>{$('#defaultBgPreview').style.backgroundImage=mediaCache.has('background:default')?`url("${mediaCache.get('background:default')}")`:''};show();$('#chooseDefaultBg').onclick=()=>$('#defaultBgFile').click();$('#defaultBgFile').onchange=async e=>{const b=$('#chooseDefaultBg');b.disabled=true;try{await mediaWrite('background:default',await prepareImage(e.target.files[0],1440));show();$('#defaultBgPreview').textContent='';toast('通用背景已保存')}catch(err){toast(err.message)}finally{b.disabled=false;e.target.value=''}};$('#resetDefaultBg').onclick=async()=>{try{await mediaWrite('background:default',null);show();$('#defaultBgPreview').textContent='浅粉默认背景';toast('已恢复默认')}catch(err){toast(err.message)}};$('#doneDefaultBg').onclick=()=>d.close()}
function renderWallet(){screen.innerHTML=`<section class="view">${wxHeading('零钱','WECHAT · VIRTUAL WALLET')}<div class="wallet-hero"><span>我的虚拟余额</span><strong>¥ ${PalaisWallet.money(wallet.balance)}</strong><p>初始余额 ¥10,000.00</p></div><div class="wallet-caption">收支明细 · ${wallet.ledger.length} 笔</div><div id="walletLedger"></div><button class="secondary full" id="backWxMe">返回微信设置</button><p class="section-note">发送红包或转账扣款，领取角色卡片入账。<br>已发送的卡片在回复失败后也会保留。<br>旧版历史卡片不会追溯扣款。</p></section>`;bindWxHome();const list=$('#walletLedger');if(!wallet.ledger.length)list.innerHTML='<div class="soft-empty">还没有收支，第一份心意正在路上。</div>';[...wallet.ledger].reverse().forEach(x=>{const row=document.createElement('div');row.className='wallet-row';row.innerHTML=`<div><strong>${x.delta<0?'发出':'收入'}${x.type==='redpacket'?'红包':'转账'} · ${escapeHtml(x.peer||chatLabel(x.conversationId))}</strong><small>${new Date(x.createdAt).toLocaleString('zh-CN')}</small><p>${escapeHtml(x.note||'一点小心意')}</p></div><div class="wallet-amount ${x.delta>0?'income':''}">${x.delta>0?'+':'−'}${PalaisWallet.money(Math.abs(x.delta))}<small>余额 ${PalaisWallet.money(x.balance)}</small></div>`;list.append(row)});$('#backWxMe').onclick=renderWxMe}
function receiveGift(r,m){if(!m?.card||m.role!=='assistant'||m.card.status!=='pending')return;const old=wallet,oldStatus=m.card.status;try{wallet=PalaisWallet.apply(wallet,{messageId:m.id,conversationId:r.id,amount:m.card.amount,direction:'in',type:m.card.type,note:m.card.note,peer:roles.find(x=>x.id===m.sender)?.name||r.name});m.card.status='received';persist();renderConversation();toast('已收入零钱 ¥'+m.card.amount)}catch(err){wallet=old;m.card.status=oldStatus;toast(err.message||'领取失败，请重试')}}
function patAvatar(r,m){if(busy)return;const speaker=m.role==='user'?profile.name:roles.find(x=>x.id===m.sender)?.name||r.name,suffix=m.role==='user'?profile.pat||'的肩膀':'的肩膀',text=m.role==='user'?`${r.name}拍了拍「${speaker}」${suffix}`:`我拍了拍「${speaker}」${suffix}`;const hist=histories[r.id]||(histories[r.id]=[]);hist.push({id:crypto.randomUUID(),role:'user',kind:'pat',content:text,createdAt:Date.now(),...(r.members?{audience:r.members.slice()}: {})});try{persist();renderConversation()}catch{hist.pop();toast('保存失败，请检查存储空间')}}
